"""Source identities and explicit review scope for the recreated atlas."""
N={}
def S(id,title,url,scope='Primary source or official reference checked for the stated narrow claim.'):
 N[id]=dict(id=id,title=title,url=url,review_scope=scope,checked='2026-10-13')
